mapper.select:
SELECT * FROM sys_operation_log


        AND operation_user LIKE CONCAT('%', #{query.operationUser}, '%')


        AND operation_module LIKE CONCAT('%', #{query.operationModule}, '%')


        AND operation_type = #{query.operationType}


        AND operation_result = #{query.operationResult}


        AND create_time >= #{query.startTime}


        AND create_time <= #{query.endTime}


ORDER BY create_time DESC
